// Differential checks of KnownConstructors-faithful.js against Lean, generated by leanscript --check
import * as M from "./KnownConstructors-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
// a union `{ tag: i, _1: …, … }` of leaf fields is shown as `i(…, …)`
function showUnion(v) {
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
// a recursive union: as `showUnion`, the fields marked in `rec[tag]` (the type itself) printed
// the same way, one level less deep (`…` at depth 0, as `showExpr` cuts it in Lean)
function showTree(v, rec, d) {
  if (d === 0) return "…";
  if (typeof v === "number") return v + "()";
  const r = rec[v.tag] || [];
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++)
    fs.push(r[i - 1] ? showTree(v["_" + i], rec, d - 1) : show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("known1", () => M.known1, "b", false);
check("test1({ tag: 0, _1: -7n })", () => M.test1({ tag: 0, _1: -7n }), "-7", false);
check("test1({ tag: 0, _1: -1n })", () => M.test1({ tag: 0, _1: -1n }), "-1", false);
check("test1({ tag: 1, _1: -7n })", () => M.test1({ tag: 1, _1: -7n }), "-7", false);
check("test1({ tag: 1, _1: -1n })", () => M.test1({ tag: 1, _1: -1n }), "-1", false);
check("test2(-7n)", () => M.test2(-7n), "", false);
check("test2(-1n)", () => M.test2(-1n), "", false);
check("test2(0n)", () => M.test2(0n), "", false);
check("test2(1n)", () => M.test2(1n), "", false);
check("test2(2n)", () => M.test2(2n), "", false);
check("test2(3n)", () => M.test2(3n), "", false);
check("test2(12n)", () => M.test2(12n), "", false);
check("test3(-7n)", () => M.test3(-7n), "#[Default, World, Default, Universe]", false);
check("test3(-1n)", () => M.test3(-1n), "#[Default, World, Default, Universe]", false);
check("test3(0n)", () => M.test3(0n), "#[Default, World, Default, Universe]", false);
check("test3(1n)", () => M.test3(1n), "#[Default, World, Default, Universe]", false);
check("test3(2n)", () => M.test3(2n), "#[Default, World, Default, Universe]", false);
check("test3(3n)", () => M.test3(3n), "#[Default, World, Default, Universe]", false);
check("test3(12n)", () => M.test3(12n), "#[Default, World, Default, Universe]", false);
check("test5(-7n)", () => M.test5(-7n), "false", false);
check("test5(-1n)", () => M.test5(-1n), "false", false);
check("test5(0n)", () => M.test5(0n), "false", false);
check("test5(1n)", () => M.test5(1n), "false", false);
check("test5(2n)", () => M.test5(2n), "false", false);
check("test5(3n)", () => M.test5(3n), "false", false);
check("test5(12n)", () => M.test5(12n), "false", false);
check("test6(\"\")", () => M.test6(""), "0", false);
check("test6(\"a\")", () => M.test6("a"), "0", false);
check("test6(\"hello world\")", () => M.test6("hello world"), "0", false);
check("test6(\"héllo, wörld\")", () => M.test6("héllo, wörld"), "0", false);
check("test6(\"abcabc\")", () => M.test6("abcabc"), "0", false);

console.log(`KnownConstructors-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
